let p = msg.payload;
if (typeof p === 'number') p = {v: p};
const v = Number(p && p.v);
if (isNaN(v)) return null;
const agg = context.get('agg') || {};
const a = agg[msg.topic] || {sum: 0, n: 0, min: v, max: v};
a.sum += v; a.n++;
a.min = Math.min(a.min, v); a.max = Math.max(a.max, v);
agg[msg.topic] = a;
context.set('agg', agg);
return null;

const agg = context.get('agg') || {};
context.set('agg', {});
const ts = new Date().toISOString().slice(0, 19).replace('T', ' '); // UTC
const readings = Object.entries(agg).map(([topic, a]) => ({
  topic, ts, avg: a.sum / a.n, min: a.min, max: a.max, n: a.n
}));
let queue = flow.get('queue') || [];
if (readings.length) queue.push({readings});
if (queue.length > 1440) queue = queue.slice(-1440); // maks ~24 jam
flow.set('queue', queue);
return queue.length ? msg : null;

const queue = flow.get('queue') || [];
if (!queue.length) return null;
msg.payload = queue[0];
msg.url = env.get('ODOO_URL') + '/aqua/ingest';
msg.method = 'POST';
msg.headers = {'Content-Type': 'application/json', 'X-Gateway-Key': env.get('ODOO_KEY')};
return msg;

if (msg.statusCode === 200) {
  const queue = flow.get('queue') || [];
  queue.shift();
  flow.set('queue', queue);
  node.status({fill: 'green', shape: 'dot', text: 'terkirim, sisa ' + queue.length});
  return queue.length ? msg : null; // kuras antrian sisa
}
node.status({fill: 'red', shape: 'ring', text: 'gagal ' + msg.statusCode});
return null;
